<?php
require_once __DIR__.'/includes/session_bootstrap.php';startVfnWebSession();require_once __DIR__.'/execute/config.php';require_once __DIR__.'/includes/language.php';require_once __DIR__.'/includes/web_session.php';require_once __DIR__.'/includes/ban_status.php';
function h($v):string{return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');}
$pdo=new PDO("mysql:host=$dbHost;dbname=$dbName;charset=utf8mb4",$dbUser,$dbPass,[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION]);
if(empty($_SESSION['web_user_id'])||!validateVfnWebSession($pdo)||(int)($_SESSION['web_op_permission']??0)<1){http_response_code(403);exit('Access denied');}
$q=trim((string)($_GET['q']??''));$like='%'.mb_substr($q,0,100).'%';
$bans=$pdo->prepare("SELECT id,username,real_name,ban_reason,ban_expires_at,banned_at FROM users WHERE is_banned=1 AND (ban_expires_at IS NULL OR ban_expires_at>NOW()) AND (:q='' OR username LIKE :like OR real_name LIKE :like OR ban_reason LIKE :like) ORDER BY banned_at DESC LIMIT 100");$bans->execute(['q'=>$q,'like'=>$like]);
$warnings=$pdo->prepare("SELECT w.*,u.username,u.real_name,a.username actor FROM user_warnings w INNER JOIN users u ON u.id=w.user_id LEFT JOIN users a ON a.id=w.issued_by_user_id WHERE w.revoked_at IS NULL AND (w.expires_at IS NULL OR w.expires_at>NOW()) AND (:q='' OR u.username LIKE :like OR u.real_name LIKE :like OR w.reason LIKE :like) ORDER BY w.created_at DESC LIMIT 100");$warnings->execute(['q'=>$q,'like'=>$like]);
$history=$pdo->prepare("SELECT l.*,u.username,a.username actor FROM user_activity_log l INNER JOIN users u ON u.id=l.user_id LEFT JOIN users a ON a.id=l.actor_user_id WHERE l.activity_key IN('activity_kicked','activity_kicked_spam','activity_banned','activity_unbanned','activity_warning_issued','activity_warning_revoked') AND (:q='' OR u.username LIKE :like OR a.username LIKE :like OR l.activity_value LIKE :like) ORDER BY l.created_at DESC LIMIT 150");$history->execute(['q'=>$q,'like'=>$like]);
?>
<!doctype html><html lang="<?php echo h($currentLanguage);?>"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?php echo h(t('moderation_center_title'));?></title><style>body{margin:0;background:#07141f;color:#d7e8ff;font-family:Arial}.shell{width:min(1450px,calc(100% - 32px));margin:28px auto}.card{background:#0d1d2a;border:1px solid #285475;border-radius:8px;padding:17px;margin:16px 0}.columns{display:grid;grid-template-columns:1fr 1fr;gap:16px}input{box-sizing:border-box;width:100%;padding:11px;background:#071521;color:#fff;border:1px solid #285475}table{width:100%;border-collapse:collapse}th,td{padding:10px;border-bottom:1px solid #203b50;text-align:left}a{color:#65bdff}.scroll{overflow:auto}@media(max-width:950px){.columns{grid-template-columns:1fr}}</style></head><body><?php require __DIR__.'/includes/header.php';?><main class="shell"><h1><?php echo h(t('moderation_center_title'));?></h1><form><input name="q" value="<?php echo h($q);?>" placeholder="<?php echo h(t('moderation_center_search'));?>"></form><div class="columns"><section class="card"><h2><?php echo h(t('moderation_active_bans'));?></h2><div class="scroll"><table><tr><th><?php echo h(t('admin_players_username'));?></th><th><?php echo h(t('moderation_reason'));?></th><th><?php echo h(t('moderation_expires'));?></th></tr><?php foreach($bans as $b):?><tr><td><a href="profile.php?id=<?php echo (int)$b['id'];?>&a=moderation"><?php echo h($b['real_name']?:$b['username']);?></a></td><td><?php echo h($b['ban_reason']);?></td><td><?php echo h($b['ban_expires_at']?:t('moderation_permanent'));?></td></tr><?php endforeach;?></table></div></section><section class="card"><h2><?php echo h(t('moderation_active_warnings'));?></h2><div class="scroll"><table><tr><th><?php echo h(t('admin_players_username'));?></th><th><?php echo h(t('moderation_reason'));?></th><th><?php echo h(t('moderation_expires'));?></th></tr><?php foreach($warnings as $w):?><tr><td><a href="profile.php?id=<?php echo (int)$w['user_id'];?>&a=moderation"><?php echo h($w['real_name']?:$w['username']);?></a></td><td><?php echo h($w['reason']);?></td><td><?php echo h($w['expires_at']?:t('moderation_permanent'));?></td></tr><?php endforeach;?></table></div></section></div><section class="card"><h2><?php echo h(t('moderation_history'));?></h2><div class="scroll"><table><tr><th><?php echo h(t('admin_staff_time'));?></th><th><?php echo h(t('admin_players_username'));?></th><th><?php echo h(t('admin_staff_action'));?></th><th><?php echo h(t('moderation_reason'));?></th><th>Staff</th></tr><?php foreach($history as $e):?><tr><td><?php echo h($e['created_at']);?></td><td><a href="profile.php?id=<?php echo (int)$e['user_id'];?>&a=moderation"><?php echo h($e['username']);?></a></td><td><?php echo h(t($e['activity_key']));?></td><td><?php echo h($e['activity_value']);?></td><td><?php echo h($e['actor']?:'SYSTEM');?></td></tr><?php endforeach;?></table></div></section></main><?php require __DIR__.'/includes/footer.php';?></body></html>
